//! Cloud shadows drifting over the world.
//!
//! The clouds themselves are not in the scene: what the player sees is their shadow on the
//! ground, which is one translucent pattern laid over the whole view. The pattern is the same
//! artwork the TypeScript client uses (`web/public/assets/cloud-shadow.svg`, generated by
//! `artifacts/cloud_shadow.py`): small voxel clouds made of half-tile diamonds, blurred once so
//! the edges fade and overlapping cells never add up their opacity, and built to repeat every
//! [`CLOUD_PERIOD_TILES`] tiles along both screen axes.
//!
//! **Why it is an overlay and not part of the scene.** A cloud shadow belongs to no cell: it is
//! tens of tiles across, it crosses chunk borders and cliffs, and it moves every frame, so
//! nothing about it can be baked and cutting it per cell would cost hundreds of meshes a frame.
//! The TypeScript client draws it as one GPU-tiled sprite above the stage
//! (`cloud-shadows.ts`), and this draws the same thing as a handful of quads over the finished
//! scene. The cost is that it darkens whatever it is over, the player and the trees included,
//! rather than only the ground — which is what a cloud's shadow does to a figure standing under
//! it anyway.
//!
//! **How it is placed.** The pattern follows the projection's origin, so it stays still on the
//! ground while the camera moves, and drifts slowly with real time ([`CLOUD_DRIFT`]) on top of
//! that. Its size is read from the period rather than from the texture, so the raster's
//! resolution is free to change without moving a cloud.

use macroquad::prelude::*;

/// The path the pattern is loaded from, relative to the client root.
///
/// A texture of its own, not a frame of the shared atlas: the packer trims the transparent
/// border off every sprite it packs, and a trimmed pattern no longer repeats — the atlas's own
/// copy of this artwork comes out 600 × 195 where the period is 600 × 300, which tiles with a
/// seam across every row of clouds.
pub const CLOUD_SHADOW_SOURCE: &str = "content/cloud-shadow.png";

/// How many tiles the pattern repeats over, along both screen axes.
///
/// `PERIOD_TILES` in `artifacts/cloud_shadow.py`, which is what makes the artwork seamless; the
/// drawn size follows from it, so a copy spans `CLOUD_PERIOD_TILES` tile widths across and as
/// many tile heights down.
pub const CLOUD_PERIOD_TILES: f64 = 12.0;

/// Opacity of the whole pattern: one flat shade, so overlapping clouds never add up.
///
/// This is the one knob for how dark the clouds are. `CLOUD_SHADOW_ALPHA` in the TypeScript
/// client's `cloud-shadows.ts` is the same number for that client.
pub const CLOUD_SHADOW_ALPHA: f32 = 0.18;

/// How fast the clouds drift, as a fraction of a tile per real second: `x` across the screen,
/// `y` down it.
///
/// The TypeScript client writes the same drift in scene pixels per second — `{x: 2, y: 0.5}` at
/// its tile of 40 × 20 px — and a tile is the one length both clients agree on, so it is kept as
/// a fraction of one here: a cloud crosses the same amount of *world* per second in both,
/// whatever either draws a tile at.
pub const CLOUD_DRIFT: (f64, f64) = (2.0 / 40.0, 0.5 / 20.0);

/// The drifting pattern of cloud shadows, and the texture it is drawn from.
pub struct CloudShadows {
    texture: Texture2D,
    /// How far the pattern has drifted, in tiles: `x` across the screen, `y` down it.
    drift: (f64, f64),
}

impl CloudShadows {
    /// The pattern at rest, drawn from `texture`.
    pub fn new(texture: Texture2D) -> Self {
        // The pattern is magnified several times over and its edges are blurred anyway, so
        // linear filtering is what keeps a cloud from showing the texels it is made of.
        texture.set_filter(FilterMode::Linear);
        Self {
            texture,
            drift: (0.0, 0.0),
        }
    }

    /// Moves the clouds on by `elapsed_ms` of real time.
    ///
    /// Real time and not simulation ticks: the drift is weather, so it keeps going at the same
    /// speed whatever the simulation is doing.
    pub fn advance(&mut self, elapsed_ms: f64) {
        self.drift.0 += CLOUD_DRIFT.0 * elapsed_ms / 1000.0;
        self.drift.1 += CLOUD_DRIFT.1 * elapsed_ms / 1000.0;
        // Wrapped at the period, so the offset stays small however long the session runs: at a
        // few hundred thousand tiles an `f64` still has plenty of precision, but the numbers the
        // placement works with stay the size of a screen.
        self.drift.0 %= CLOUD_PERIOD_TILES;
        self.drift.1 %= CLOUD_PERIOD_TILES;
    }

    /// Draws the pattern over the view, as many copies as it takes to cover it.
    ///
    /// `origin` is the projection's own origin, so the clouds hold their place on the ground as
    /// the camera moves; `screen` is the view in pixels.
    pub fn draw(&self, origin: (f64, f64), tile: (f64, f64), screen: (f64, f64)) {
        let period = (CLOUD_PERIOD_TILES * tile.0, CLOUD_PERIOD_TILES * tile.1);
        // Black, not the artwork's own colour: the shader multiplies, so this makes the
        // shade neutral however the pattern was drawn, and only its alpha is read.
        let colour = Color::new(0.0, 0.0, 0.0, CLOUD_SHADOW_ALPHA);
        for (x, y) in cloud_copies(
            (
                origin.0 - self.drift.0 * tile.0,
                origin.1 - self.drift.1 * tile.1,
            ),
            period,
            screen,
        ) {
            draw_texture_ex(&self.texture, x as f32, y as f32, colour, DrawTextureParams {
                dest_size: Some(vec2(period.0 as f32, period.1 as f32)),
                ..Default::default()
            });
        }
    }
}

/// Where each copy of the pattern goes to cover a `screen`-sized view, given one copy's top left
/// corner at `anchor` and a period of `period` pixels.
///
/// The pattern repeats, so the copy that matters is the one nearest the view: the anchor is
/// brought back to within a period of the top left corner and the copies walk from there. Drawing
/// from the anchor itself works out the same but asks for a copy per period the camera has
/// travelled, which after a walk across the world is thousands of them.
pub fn cloud_copies(anchor: (f64, f64), period: (f64, f64), screen: (f64, f64)) -> Vec<(f64, f64)> {
    if !(period.0 > 0.0 && period.1 > 0.0) {
        return Vec::new();
    }
    let start = |anchor: f64, period: f64| anchor - (anchor / period).ceil() * period;
    let (first_x, first_y) = (start(anchor.0, period.0), start(anchor.1, period.1));
    let mut copies = Vec::new();
    let mut y = first_y;
    while y < screen.1 {
        let mut x = first_x;
        while x < screen.0 {
            copies.push((x, y));
            x += period.0;
        }
        y += period.1;
    }
    copies
}

